-- 10 test accounts, one per test user (UserService/docs/seed_test_users.sql), all ACTIVE with 10,000,000.
--   account_id     01900000-0000-7000-8001-0000000000NN
--   user_id        01900000-0000-7000-8000-0000000000NN   (test.userNN@example.com)
--   account_number 10000000NN
--
--   docker exec -i mysql-local mysql -uroot -proot123 account < AccountService/docs/seed_test_accounts.sql
--
-- Times are written in Asia/Ho_Chi_Minh (UTC+7) because the app reads them with serverTimezone=Asia/Ho_Chi_Minh.
-- Re-run: DELETE FROM accounts WHERE account_number LIKE '10000000__'; first.
SET @now = DATE_ADD(UTC_TIMESTAMP(6), INTERVAL 7 HOUR);

